// ===== EDITE AQUI: nome da loja (igual esta escrito na planilha) => ID da loja no Bling =====
const LOJAS = {
  'Shopee': 111111111,
  'Mercado Livre': 222222222,
};
// ===========================================================================================

const produto = $('Recebe produto').first().json;

// deixa a busca pelo nome da loja sem diferenca de maiusculas/minusculas e espacos
const lojas = {};
for (const nome in LOJAS) lojas[nome.trim().toLowerCase()] = LOJAS[nome];

function lerPreco(valor) {
  if (typeof valor === 'number') return valor;
  let texto = String(valor || '').replace('R$', '').replace(/\s/g, '');
  if (texto.includes(',')) texto = texto.replace(/\./g, '').replace(',', '.');
  return Number(texto);
}

const saida = [];
for (const linha of $input.all()) {
  const nomeLoja = String(linha.json.Loja || '').trim();
  const idLoja = lojas[nomeLoja.toLowerCase()];
  if (!idLoja) {
    throw new Error(`A loja "${nomeLoja}" nao esta na lista LOJAS do no "Monta vinculos".`);
  }
  const preco = lerPreco(linha.json.Preco);
  if (!preco) {
    throw new Error(`Preco invalido para a loja "${nomeLoja}": ${linha.json.Preco}`);
  }
  saida.push({
    json: {
      codigo: String(produto.codigo),
      preco: preco,
      produto: { id: Number(produto.idProduto) },
      loja: { id: idLoja }
    }
  });
}

return saida;
